-- METATYA Sports OS — result verification integrity guard.
-- Additive, data-preserving migration. Does not rewrite existing result rows.
-- Authenticated inserts always start pending; only an active tenant owner/admin
-- may transition verification_status. The actor/time are generated by the DB.
-- This protects direct PostgREST writes as well as application API requests.

BEGIN;

CREATE OR REPLACE FUNCTION public.sports_guard_results_verification()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog
AS $function$
DECLARE
  v_actor_id uuid;
  v_can_verify boolean := false;
BEGIN
  v_actor_id := auth.uid();

  IF TG_OP = 'INSERT' THEN
    -- Never trust client-supplied verification metadata, including admin clients.
    NEW.verification_status := 'pending_review';
    NEW.verified_by := NULL;
    NEW.verified_at := NULL;
    RETURN NEW;
  END IF;

  -- Ordinary result edits must not alter verification metadata.
  IF NEW.verification_status IS NOT DISTINCT FROM OLD.verification_status
     AND NEW.verified_by IS NOT DISTINCT FROM OLD.verified_by
     AND NEW.verified_at IS NOT DISTINCT FROM OLD.verified_at THEN
    RETURN NEW;
  END IF;

  -- Metadata cannot be edited independently of a status transition.
  IF NEW.verification_status IS NOT DISTINCT FROM OLD.verification_status THEN
    RAISE EXCEPTION 'Verification metadata can only change with verification status'
      USING ERRCODE = '42501';
  END IF;

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated owner/admin required to verify a result'
      USING ERRCODE = '42501';
  END IF;

  -- SECURITY INVOKER is intentional: RLS on memberships limits this lookup
  -- to the caller's own membership rows.
  SELECT EXISTS (
    SELECT 1
    FROM public.sports_tenant_memberships AS tm
    WHERE tm.tenant_id = NEW.tenant_id
      AND tm.user_id = v_actor_id
      AND tm.status = 'active'
      AND tm.role IN ('owner', 'admin')
  )
  INTO v_can_verify;

  IF NOT v_can_verify THEN
    RAISE EXCEPTION 'Active tenant owner/admin required to change result verification'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.verification_status = 'pending_review' THEN
    NEW.verified_by := NULL;
    NEW.verified_at := NULL;
  ELSE
    -- The database, not the client, records who performed the transition.
    NEW.verified_by := v_actor_id;
    NEW.verified_at := pg_catalog.now();
  END IF;

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.sports_guard_results_verification()
  FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS sports_results_verification_guard
  ON public.sports_results;

CREATE TRIGGER sports_results_verification_guard
BEFORE INSERT OR UPDATE ON public.sports_results
FOR EACH ROW
EXECUTE FUNCTION public.sports_guard_results_verification();

COMMENT ON FUNCTION public.sports_guard_results_verification() IS
  'Forces new results to pending_review and restricts verification transitions to active tenant owners/admins.';

COMMENT ON TRIGGER sports_results_verification_guard
  ON public.sports_results IS
  'Database-level integrity guard for result verification metadata.';

COMMIT;
